-- db/operations/apply_story_clusters.sql
--
-- The story-cluster DRAFT of the résumé (28 Sep 2026): every experience bullet re-told as
-- problem, then decisions, then outcome, plus a problem-first headline and summary. It
-- writes ONLY the variant 'variant:story-clusters'; the master is never touched.
-- Generated from the adjudicated drafts of workflow run wf_3971e59d-a9c (PENDING.md).
--
--   psql -d jobs_tracker_v2 -v ON_ERROR_STOP=1 -c "select set_config('variant.name','story-clusters',false)" \
--        -f db/operations/clone_master_variant.sql            # once
--   psql -d jobs_tracker_v2 -v ON_ERROR_STOP=1 -f db/operations/apply_story_clusters.sql   # re-runnable
--
-- Re-runnable: it deletes the variant's blocks in the sections it rewrites and inserts the
-- draft again. Skills sections are not rewritten.

\set ON_ERROR_STOP on
BEGIN;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM resume_documents WHERE doc_key = 'variant:story-clusters') THEN
        RAISE EXCEPTION 'no variant:story-clusters -- run clone_master_variant.sql with variant.name story-clusters first';
    END IF;
END $$;

DELETE FROM resume_blocks
 WHERE doc_key = 'variant:story-clusters'
   AND section_id IN ('p-cura', 'p-elpaso', 'p-innroad', 'p-lynton', 'p-mcd', 'quick-deque', 'quick-headline', 'quick-rocket', 'quick-summary', 'quick-teletext', 'quick-voltuswave-cofounder', 'quick-vp');


COMMIT;
